//! The pin between the TypeScript codec module that `[backend.typescript]
//! codec = true` writes and the `wasm` module of the generated Rust crate.
//!
//! The codec module resolves a wasm type id by name at load and reads a rule
//! code as an index into its `RULES`, so the names and the order it lists must
//! be the ones `WASM_PAYLOAD_TYPES` and `WASM_RULES` hold, and its
//! `CATALOG_HASH` must be the hash the module writes. These tests read both
//! generated files of one build and compare them; they also cover the
//! manifest rules of the `codec` key: it implies the wasm module, a written
//! `wasm = false` is refused with MANI-019, and an implied module without
//! `flatbuffers` is refused with its own wording.

use std::path::Path;

use ridlc::{CliRun, Emit};

#[allow(
    dead_code,
    reason = "these tests copy the cabin example and compile nothing, so the \
              rlib helpers of the module are not called here"
)]
mod support;

/// The manifest of `examples/cabin`, which sets `wasm = true`, with its
/// `[backend.typescript]` table removed: each test adds the tables it needs.
fn cabin_manifest() -> String {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../examples/cabin/ridl.toml");
    let manifest = std::fs::read_to_string(path).expect("the manifest is read");
    assert!(
        manifest.lines().any(|line| line.trim() == "wasm = true"),
        "the tests expect `wasm = true` in the example's manifest:\n{manifest}"
    );
    let stripped = support::without_typescript_table(&manifest);
    assert!(!stripped.contains("codec"), "{stripped}");
    stripped
}

/// The table that turns the codec module on.
const CODEC_TABLE: &str = "\n[backend.typescript]\ncodec = true\n";

/// Copies the cabin example with `manifest` into `work/src`, builds it with
/// both emits into `work/out`, and returns the run and the output directory.
fn build_cabin(work: &Path, manifest: &str) -> (CliRun, std::path::PathBuf) {
    let src = work.join("src");
    let out = work.join("out");
    std::fs::create_dir_all(&src).expect("the source directory is created");
    support::copy_cabin(&src, manifest);
    let run = ridlc::run_build(&src, &out, &[Emit::Rust, Emit::TypeScript], false.into())
        .expect("the build runs");
    (run, out)
}

/// Fails with the messages of `run` when it has an error.
fn assert_clean(run: &CliRun) {
    assert!(
        !run.has_error(),
        "the build must be clean, diagnostics: {:?}",
        run.diagnostics
            .iter()
            .map(|diagnostic| (diagnostic.code.as_str(), &diagnostic.message))
            .collect::<Vec<_>>()
    );
}

/// Whitespace-stripped copy of `source`.
fn dense(source: &str) -> String {
    source.chars().filter(|c| !c.is_whitespace()).collect()
}

/// The text between `head` and the next `]` of the whitespace-stripped
/// `source`, split on `,`, with the quotes trimmed. Empty items, which a
/// trailing comma leaves, are dropped.
fn list_after(source: &str, head: &str) -> Vec<String> {
    let d = dense(source);
    let at = d
        .find(head)
        .unwrap_or_else(|| panic!("`{head}` is in:\n{source}"));
    let body = &d[at + head.len()..];
    let end = body.find(']').expect("the list is closed");
    body[..end]
        .split(',')
        .map(|item| item.trim_matches('"').to_string())
        .filter(|item| !item.is_empty())
        .collect()
}

/// The `WASM_PAYLOAD_TYPES` and `WASM_RULES` lists of a `__ridl_wasm.rs`.
fn wasm_lists(wasm: &str) -> (Vec<String>, Vec<String>) {
    (
        list_after(wasm, "WASM_PAYLOAD_TYPES:&[&str]=&["),
        list_after(wasm, "WASM_RULES:&[&str]=&["),
    )
}

/// The `PAYLOAD_TYPES` list of a codec module, the text from `[` to
/// `] as const`.
fn codec_types(codec: &str) -> Vec<String> {
    let d = dense(codec);
    assert!(d.contains("]asconst;"), "{codec}");
    list_after(codec, "exportconstPAYLOAD_TYPES=[")
}

/// The `RULES` list of a codec module.
fn codec_rules(codec: &str) -> Vec<String> {
    list_after(codec, "exportconstRULES=[")
}

/// Whether `part` is a subsequence of `whole`, order kept.
fn is_subsequence(part: &[String], whole: &[String]) -> bool {
    let mut rest = whole.iter();
    part.iter()
        .all(|item| rest.any(|candidate| candidate == item))
}

#[test]
fn a_build_with_codec_writes_the_codec_file_beside_the_wasm_module() {
    let work = tempfile::tempdir().expect("a temp dir is created");
    let (run, out) = build_cabin(work.path(), &format!("{}{CODEC_TABLE}", cabin_manifest()));
    assert_clean(&run);
    let codec =
        std::fs::read_to_string(out.join("veh.cabin.codec.ts")).expect("the codec file is written");
    assert_eq!(
        codec.lines().next(),
        Some("// @generated by ridl from package veh.cabin. Do not edit."),
        "{codec}"
    );
    assert!(out.join("__ridl_wasm.rs").exists());

    let work = tempfile::tempdir().expect("a temp dir is created");
    let (run, out) = build_cabin(work.path(), &cabin_manifest());
    assert_clean(&run);
    assert!(out.join("veh.cabin.ts").exists());
    assert!(
        !out.join("veh.cabin.codec.ts").exists(),
        "without `codec` the build writes no codec file"
    );
}

#[test]
fn the_codec_table_names_what_the_wasm_module_lists() {
    let work = tempfile::tempdir().expect("a temp dir is created");
    let (run, out) = build_cabin(work.path(), &format!("{}{CODEC_TABLE}", cabin_manifest()));
    assert_clean(&run);
    let wasm = std::fs::read_to_string(out.join("__ridl_wasm.rs")).expect("the module is written");
    let codec =
        std::fs::read_to_string(out.join("veh.cabin.codec.ts")).expect("the codec file is written");

    let (wasm_types, wasm_rules) = wasm_lists(&wasm);
    assert!(!wasm_types.is_empty(), "{wasm}");
    assert_eq!(codec_types(&codec), wasm_types);
    assert_eq!(codec_rules(&codec), wasm_rules);

    let rust_hash = list_after(&wasm, "constCATALOG_HASH:[::core::primitive::u8;32]=[");
    let ts_hash = list_after(
        &codec,
        "exportconstCATALOG_HASH:Uint8Array=Uint8Array.from([",
    );
    assert_eq!(rust_hash.len(), 32, "{wasm}");
    assert_eq!(ts_hash, rust_hash);
}

#[test]
fn each_package_lists_a_subsequence_of_the_crate_list() {
    let fixture = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/codec-two-packages");
    let work = tempfile::tempdir().expect("a temp dir is created");
    let out = work.path().join("out");
    let run = ridlc::run_build(
        &fixture,
        &out,
        &[Emit::Rust, Emit::TypeScript],
        false.into(),
    )
    .expect("the build runs");
    assert_clean(&run);
    let wasm = std::fs::read_to_string(out.join("__ridl_wasm.rs")).expect("the module is written");
    let (crate_list, _) = wasm_lists(&wasm);
    assert_eq!(crate_list, ["pin.a.Zed", "pin.b.Alpha"]);

    let mut joined = Vec::new();
    for package in ["pin.a", "pin.b"] {
        let codec = std::fs::read_to_string(out.join(format!("{package}.codec.ts")))
            .expect("the codec file is written");
        let types = codec_types(&codec);
        assert!(
            is_subsequence(&types, &crate_list),
            "{package}: {types:?} in {crate_list:?}"
        );
        joined.extend(types);
    }
    assert_eq!(joined, crate_list);
}

#[test]
fn codec_implies_the_wasm_module() {
    let manifest: String = cabin_manifest()
        .lines()
        .filter(|line| line.trim() != "wasm = true")
        .map(|line| format!("{line}\n"))
        .collect();
    let work = tempfile::tempdir().expect("a temp dir is created");
    let (run, out) = build_cabin(work.path(), &format!("{manifest}{CODEC_TABLE}"));
    assert_clean(&run);
    assert!(out.join("veh.cabin.codec.ts").exists());
    assert!(out.join("__ridl_wasm.rs").exists());
    let cargo_toml = std::fs::read_to_string(out.join("Cargo.toml")).expect("Cargo.toml");
    assert!(
        cargo_toml
            .lines()
            .any(|line| line == "wasm-exports = [\"std\"]"),
        "{cargo_toml}"
    );
}

#[test]
fn codec_with_wasm_false_writes_nothing() {
    let manifest = cabin_manifest().replace("wasm = true", "wasm = false");
    let work = tempfile::tempdir().expect("a temp dir is created");
    let (run, out) = build_cabin(work.path(), &format!("{manifest}{CODEC_TABLE}"));
    assert!(
        run.diagnostics
            .iter()
            .any(|diagnostic| diagnostic.code.as_str() == "MANI-019"
                && diagnostic.severity == ridl_core::diag::Severity::Error),
        "{:?}",
        run.diagnostics
    );
    assert!(!out.join("veh.cabin.codec.ts").exists());
    assert!(!out.join("veh.cabin.ts").exists());
}

#[test]
fn an_implied_wasm_without_flatbuffers_is_refused_with_the_implied_wording() {
    let manifest: String = cabin_manifest()
        .lines()
        .filter(|line| line.trim() != "wasm = true")
        .map(|line| {
            if line.trim_start().starts_with("encodings") {
                "encodings = [\"proto3\"]\n".to_string()
            } else {
                format!("{line}\n")
            }
        })
        .collect();
    let work = tempfile::tempdir().expect("a temp dir is created");
    let (run, out) = build_cabin(work.path(), &format!("{manifest}{CODEC_TABLE}"));
    let messages: Vec<&str> = run
        .diagnostics
        .iter()
        .filter(|diagnostic| diagnostic.severity == ridl_core::diag::Severity::Error)
        .map(|diagnostic| diagnostic.message.as_str())
        .collect();
    assert!(
        messages.contains(
            &"`wasm` is implied by `codec = true` in the manifest, and `[backend.rust] \
              encodings` does not name `flatbuffers`, which every export of the `wasm` module \
              checks"
        ),
        "{messages:?}"
    );
    assert!(!out.join("__ridl_wasm.rs").exists());
}

/// A written `wasm = true` beside `codec = true` keeps the written wording
/// when `encodings` does not name `flatbuffers`: the module is not implied.
#[test]
fn a_written_wasm_without_flatbuffers_keeps_the_written_wording() {
    let manifest = cabin_manifest().replace(
        "encodings = [\"flatbuffers\", \"proto3\", \"podbuf\"]",
        "encodings = [\"proto3\", \"podbuf\"]",
    );
    assert!(!manifest.contains("flatbuffers"), "{manifest}");
    assert!(manifest.contains("wasm = true"), "{manifest}");
    let work = tempfile::tempdir().expect("a temp dir is created");
    let (run, out) = build_cabin(work.path(), &format!("{manifest}{CODEC_TABLE}"));
    let messages: Vec<&str> = run
        .diagnostics
        .iter()
        .filter(|diagnostic| diagnostic.severity == ridl_core::diag::Severity::Error)
        .map(|diagnostic| diagnostic.message.as_str())
        .collect();
    assert!(
        messages.contains(
            &"`[backend.rust] wasm = true` needs `encodings` to name `flatbuffers`, because the \
              `wasm` module checks FlatBuffers payloads"
        ),
        "{messages:?}"
    );
    assert!(!out.join("__ridl_wasm.rs").exists());
}

/// Writes a one-package workspace with `codec = true` whose one source is
/// `source`, builds it with the TypeScript emit, and returns the output
/// directory.
fn build_only(work: &Path, source: &str) -> std::path::PathBuf {
    let src = work.join("src");
    let out = work.join("out");
    std::fs::create_dir_all(&src).expect("the source directory is created");
    std::fs::write(
        src.join("ridl.toml"),
        "[package]\nname = \"only\"\nversion = \"1.0.0\"\n\n[backend.rust]\n\
         encodings = [\"flatbuffers\"]\n\n[backend.typescript]\ncodec = true\n",
    )
    .expect("the manifest is written");
    std::fs::write(src.join("only.ridl"), source).expect("the source is written");
    let run =
        ridlc::run_build(&src, &out, &[Emit::TypeScript], false.into()).expect("the build runs");
    assert_clean(&run);
    out
}

/// A package that names a `ridl.std` type as a field only gets `ridl.std.ts`
/// and no `ridl.std.codec.ts`: no codec module imports one.
#[test]
fn a_std_type_used_as_a_field_writes_no_std_codec_file() {
    let work = tempfile::tempdir().expect("a temp dir is created");
    let out = build_only(
        work.path(),
        "package only\n\n/// A tag.\nstruct Tag {\n  /// The label.\n  label : Label\n}\n\n\
         /// Tags.\ninterface Tags {\n  /// The tag.\n  event tag : Tag @[100ms..1s]\n}\n",
    );
    assert!(out.join("only.ts").exists());
    assert!(out.join("only.codec.ts").exists());
    assert!(out.join("ridl.std.ts").exists());
    assert!(
        !out.join("ridl.std.codec.ts").exists(),
        "no codec module imports ridl.std's"
    );
}

/// A package with no payload type gets no codec file.
#[test]
fn a_package_with_only_a_constant_writes_no_codec_file() {
    let work = tempfile::tempdir().expect("a temp dir is created");
    let out = build_only(
        work.path(),
        "package only\n\n/// A limit.\nconst LIMIT : integer = 6\n",
    );
    assert!(out.join("only.ts").exists());
    assert!(!out.join("only.codec.ts").exists());
}

/// A payload type that is a `ridl.std` scalar makes its package's codec
/// module import `ridl.std.codec.ts`, which is then written.
#[test]
fn a_std_payload_type_writes_the_std_codec_file() {
    let fixture =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../ridl-backend-ts/tests/fixtures/codec");
    let work = tempfile::tempdir().expect("a temp dir is created");
    let out = work.path().join("out");
    let run = ridlc::run_build(&fixture, &out, &[Emit::TypeScript], false.into())
        .expect("the build runs");
    assert_clean(&run);
    let codec = std::fs::read_to_string(out.join("veh.common.codec.ts")).expect("the codec file");
    assert!(
        codec.contains("import * as ridl_std_codec from \"./ridl.std.codec.js\";"),
        "{codec}"
    );
    let std_codec =
        std::fs::read_to_string(out.join("ridl.std.codec.ts")).expect("the std codec file");
    assert!(
        std_codec.contains("export function encodeName("),
        "{std_codec}"
    );
}

/// A package whose only payload root is a `ridl.std` scalar gets its codec
/// file, which imports `ridl.std.codec.ts`, and that file is written too.
#[test]
fn a_package_whose_only_payload_root_is_foreign_writes_both_codec_files() {
    let fixture = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../ridl-backend-ts/tests/fixtures/codec-foreign-only");
    let work = tempfile::tempdir().expect("a temp dir is created");
    let out = work.path().join("out");
    let run = ridlc::run_build(&fixture, &out, &[Emit::TypeScript], false.into())
        .expect("the build runs");
    assert_clean(&run);
    let codec = std::fs::read_to_string(out.join("veh.names.codec.ts")).expect("the codec file");
    assert!(
        codec.contains("import * as ridl_std_codec from \"./ridl.std.codec.js\";"),
        "{codec}"
    );
    assert!(!codec.contains("./veh/names.js"), "{codec}");
    assert!(out.join("ridl.std.codec.ts").exists());
}
